def construct():
    result = batches()
    if result is not None:
        return result
    state = root()
    tried = set()
    while remaining() > 0:
        if complete(state):
            return state
        opts = candidates(state)
        if not opts:
            return None
        scored = []
        for c in opts:
            cid = c['id']
            if cid in tried:
                continue
            kind = c['kind']
            slack = c.get('slack', 9999)
            start = c.get('start', 0)
            if kind == 'forge':
                score = slack * 1.0 + start * 0.001
            elif kind == 'finish':
                score = slack * 0.8 + start * 0.001
            else:
                score = slack * 1.2 + start * 0.001
            scored.append((score, cid))
        if not scored:
            return None
        scored.sort(key=lambda x: x[0])
        best_id = scored[0][1]
        tried.add(best_id)
        state = advance(state, best_id)
    return None
